form.script:
var gks = Packages.gks;

function formValues() {
	var values = {};
	var k;
	for (var i = 0; i < arguments.length; ++i) {
		k = arguments[i];
		values[k] = form.model.getValue(k);
	}
	return values;
}

function beforeCommit(values) {
	var f = formValues('startFeature', 'direction', 'phases', 'stopConditions');
	var trace = new gks.clark.trace.ElectricTraceSession();
	if (f.phases) {
		trace.phases = f.phases;
	}
	if (f.direction) {
		trace.direction = f.direction;
	}
	trace.startFeature = f.startFeature;
	if (f.stopConditions) {
		trace.stopConditions = f.stopConditions;
	}
	values.traceSession = trace;
	values.traceID = null;
}

function beforeUpdate(values) {
	var p = values['phases'];
	if (!p || p.length == 0) {
		values['phases'] = gks.trace.electric.Phase.values();
	}
	if (!values['direction']) {
		values['direction'] = gks.trace.electric.TraceDirection.DOWN;
	}
}

function validate(result) {
	var f = formValues('startFeature', 'direction', 'phases');
	if (!f.startFeature) {
		result.error("A start feature must be chosen");
	}
	if (!f.direction) {
		result.error("A trace direction must be chosen");
	}
	if (!f.phases) {
		result.error("One or more trace phases must be chosen");
	}
	return null;
}

function test(v) {
	return v ? true : false;
}
